CREATE OR REPLACE FUNCTION public.sync_waste_out_producer_signature() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ BEGIN IF NEW.job_type = 'waste_out' THEN UPDATE public.route_one_jobs SET customer_signature = NEW.operator_signature, customer_signoff_name = NEW.operator_name, customer_signoff_at = CASE WHEN NEW.operator_signature IS NOT NULL THEN NEW.first_weigh_at ELSE NULL END, disposer_signature = CASE WHEN NEW.disposer_signature IS DISTINCT FROM OLD.disposer_signature THEN NEW.disposer_signature ELSE disposer_signature END, disposer_name = CASE WHEN NEW.disposer_name IS DISTINCT FROM OLD.disposer_name THEN NEW.disposer_name ELSE disposer_name END, disposer_signoff_at = CASE WHEN NEW.disposer_signoff_at IS DISTINCT FROM OLD.disposer_signoff_at THEN NEW.disposer_signoff_at ELSE disposer_signoff_at END WHERE weighbridge_transaction_id = NEW.id AND job_type = 'waste_out_skip'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER sync_waste_out_disposal_evidence AFTER UPDATE OF disposer_signature, disposer_name, disposer_signoff_at ON public.weighbridge_transactions FOR EACH ROW EXECUTE FUNCTION public.sync_waste_out_producer_signature();